const listFleetNodesByOwner = `-- name: ListFleetNodesByOwner :many
SELECT id, namespace, owner_id, created_at, updated_at, container_id, daemon_id, name, spec, image, profile_ref, start_epoch, data_volume, secrets_volume, desired, status, generation, ready, health_at, active_runs, pending_reports, failed_reports, maintenance, revoked, error_code, error_message, spec_config FROM fleet_nodes WHERE namespace = $1 AND owner_id = $2
ORDER BY created_at, id LIMIT $4 OFFSET $3
`

type ListFleetNodesByOwnerParams struct {
	Namespace  string      `json:"namespace"`
	OwnerID    pgtype.UUID `json:"owner_id"`
	PageOffset int32       `json:"page_offset"`
	PageLimit  int32       `json:"page_limit"`
}

func (q *Queries) ListFleetNodesByOwner(ctx context.Context, arg ListFleetNodesByOwnerParams) ([]FleetNode, error) {
	rows, err := q.db.Query(ctx, listFleetNodesByOwner,
		arg.Namespace,
		arg.OwnerID,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FleetNode{}
	for rows.Next() {
		var i FleetNode
		if err := rows.Scan(
			&i.ID,
			&i.Namespace,
			&i.OwnerID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ContainerID,
			&i.DaemonID,
			&i.Name,
			&i.Spec,
			&i.Image,
			&i.ProfileRef,
			&i.StartEpoch,
			&i.DataVolume,
			&i.SecretsVolume,
			&i.Desired,
			&i.Status,
			&i.Generation,
			&i.Ready,
			&i.HealthAt,
			&i.ActiveRuns,
			&i.PendingReports,
			&i.FailedReports,
			&i.Maintenance,
			&i.Revoked,
			&i.ErrorCode,
			&i.ErrorMessage,
			&i.SpecConfig,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

